const req = $('Kapso Webhook').first().json;
const headers = req.headers || {};
const calculated = String($input.first().json.signatureCalculated ?? $input.first().json.data ?? '').trim().toLowerCase();
const supplied = String(headers['x-webhook-signature'] ?? '').trim().toLowerCase();
const safeEqual = (a, b) => {
  let diff = a.length ^ b.length;
  const n = Math.max(a.length, b.length);
  for (let i = 0; i < n; i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return diff === 0;
};
const event = String(headers['x-webhook-event'] ?? '');
const version = String(headers['x-webhook-payload-version'] ?? '');
const eventId = String(headers['x-idempotency-key'] ?? '');
return [{ json: {
  signatureValid: supplied.length > 0 && calculated.length > 0 && safeEqual(calculated, supplied),
  eventValid: event === 'whatsapp.message.received',
  versionValid: version === 'v2',
  eventIdPresent: eventId.length > 0,
  event,
  version,
  eventId
} }];

const req = $('Kapso Webhook').first().json;
const headers = req.headers || {};
const body = req.body || {};
const headerEventId = String(headers['x-idempotency-key'] || '');
if (body.batch === true) throw new Error('KAPSO_BATCH_NOT_SUPPORTED_V1');
const entry = body.data && !Array.isArray(body.data) ? body.data : body;
const message = entry.message || body.message;
const conversation = entry.conversation || body.conversation || {};
if (!message || !message.id) throw new Error('KAPSO_MESSAGE_ID_REQUIRED');
const kapso = message.kapso || {};
const direction = String(kapso.direction || 'inbound');
if (direction !== 'inbound') throw new Error('KAPSO_NON_INBOUND_MESSAGE');
const type = String(message.type || 'unknown');
const mediaTypes = new Set(['image','video','audio','document','sticker']);
const mediaObject = mediaTypes.has(type) && message[type] && typeof message[type] === 'object' ? message[type] : null;
const text = kapso.content ?? message.text?.body ?? mediaObject?.caption ?? message.caption ?? null;
const providerPhoneNumberId = String(entry.phone_number_id || kapso.phone_number_id || conversation.phone_number_id || body.phone_number_id || '');
if (!providerPhoneNumberId) throw new Error('KAPSO_PHONE_NUMBER_ID_REQUIRED');
const occurredAt = Number.isFinite(Number(message.timestamp))
  ? new Date(Number(message.timestamp) * 1000).toISOString()
  : new Date().toISOString();
const normalized = {
  schemaVersion: '1.0',
  channel: 'whatsapp',
  provider: 'kapso',
  providerPhoneNumberId,
  providerEventId: headerEventId,
  providerMessageId: String(message.id),
  threadId: String(kapso.whatsapp_conversation_id || conversation.id || message.from || ''),
  senderId: String(message.from || kapso.phone_number || conversation.phone_number || ''),
  direction: 'inbound',
  messageType: type,
  text: text == null ? null : String(text),
  media: mediaObject ? {
    providerMediaId: mediaObject.id ? String(mediaObject.id) : null,
    mediaType: type,
    mimeType: mediaObject.mime_type ? String(mediaObject.mime_type) : null,
    fileName: mediaObject.filename ? String(mediaObject.filename) : null,
    caption: mediaObject.caption ? String(mediaObject.caption) : null
  } : null,
  occurredAt,
  idempotencyKey: `kapso:${providerPhoneNumberId}:${String(message.id)}`,
  providerMeta: {
    origin: kapso.origin ? String(kapso.origin) : null,
    contactName: kapso.contact_name ? String(kapso.contact_name) : null
  }
};
return [{ json: normalized }];
